#include <bits/stdc++.h>
#define BIG_INF 17446744073709551616ULL
#define ULL_TYPE unsigned long long
using namespace std;

ULL mod_value, n_value, k_value, dp_array[18][250005];
ULL factorials[250005], inv_factorials[250005];

ULL fast_power(ULL_TYPE base, ULL_TYPE exponent) {
    ULL_TYPE result = 1ULL, current = base;
    while (exponent > 0) {
        if (exponent & 1ULL) result = (result * current) % mod_value;
        current = (current * current) % mod_value;
        exponent >>= 1ULL;
    }
    return result;
}

ULL nCr(int a, int b) {
    return (((factorials[a] * inv_factorials[b]) % mod_value) * inv_factorials[a - b]) % mod_value;
}

ULL compute_result() {
    int i, j, mask;
    factorials[0] = 1ULL;
    for (i = 1; i <= n_value; i++) {
        factorials[i] = (factorials[i - 1] * (ULL)i) % mod_value;
    }
    inv_factorials[n_value] = fast_power(factorials[n_value], mod_value - 2ULL);
    for (i = n_value - 1; i >= 0; i--) {
        inv_factorials[i] = (inv_factorials[i + 1] * (ULL)(i + 1)) % mod_value;
    }
    for (i = 1; i <= n_value; i++) {
        dp_array[1][i] = inv_factorials[i];
    }
    ULL total_ans = dp_array[1][n_value] * nCr(k_value, 1) % mod_value;
    int max_iter = min(17, (int)k_value);
    for (i = 2; i <= max_iter; i++) {
        for (j = n_value; j > 0; j = (j - 1) & n_value) {
            if (dp_array[i - 1][j] == 0) continue;
            int remaining_mask = n_value ^ j;
            for (mask = remaining_mask; mask > 0; mask = (mask - 1) & remaining_mask) {
                dp_array[i][j + mask] += dp_array[i - 1][j] * inv_factorials[mask];
                if (dp_array[i][j + mask] > BIG_INF) dp_array[i][j + mask] %= mod_value;
            }
        }
        for (j = n_value; j > 0; j = (j - 1) & n_value) {
            dp_array[i][j] %= mod_value;
        }
        total_ans += dp_array[i][n_value] * nCr(k_value, i);
        total_ans %= mod_value;
    }
    total_ans *= factorials[n_value];
    total_ans %= mod_value;
    return total_ans;
}

int main() {
    cin >> n_value >> k_value >> mod_value;
    ULL res = fast_power(k_value, n_value);
    if (n_value % 2 == 0) {
        res = (res - compute_result() + mod_value) % mod_value;
    }
    cout << res << endl;
    return 0;
}
